## 3️⃣ Module 1 – Fleet Telemetry Tracker

### 3.1 Core Contracts

```csharp
public record GpsSample(string VehicleId, double Latitude, double Longitude, DateTime Timestamp);

public interface IGpsProvider
{
    IAsyncEnumerable<GpsSample> GetStream(CancellationToken ct);
}
```

### 3.2 Simulated GPS Provider (for demo)

```csharp
public sealed class GpsProviderSimulator : IGpsProvider
{
    private readonly string _vehicleId;
    private readonly Random _rnd = new();

    public GpsProviderSimulator(string vehicleId) => _vehicleId = vehicleId;

    public async IAsyncEnumerable<GpsSample> GetStream([EnumeratorCancellation] CancellationToken ct)
    {
        double lat = 40.0, lon = -74.0; // start somewhere

        while (!ct.IsCancellationRequested)
        {
            // Simulate a small move (≈ 10‑30 m per tick)
            lat += (_rnd.NextDouble() - 0.5) * 0.0001;
            lon += (_rnd.NextDouble() - 0.5) * 0.0001;

            yield return new GpsSample(_vehicleId, lat, lon, DateTime.UtcNow);
            await Task.Delay(TimeSpan.FromSeconds(1), ct);
        }
    }
}
```

### 3.3 Telemetry Processor (single consumer)

```csharp
public sealed class VehicleTelemetry
{
    public string VehicleId { get; init; }
    public GpsSample LastSample { get; private set; }
    public double LastSpeedKmh { get; private set; }

    public VehicleTelemetry(string vehicleId) => VehicleId = vehicleId;
    public void Update(GpsSample sample, double speedKmh)
    {
        LastSample = sample;
        LastSpeedKmh = speedKmh;
    }
}

// Event that other modules may care about
public sealed record SpeedAnomalyEvent(string VehicleId, double SpeedKmh, double ThresholdKmh) : IEvent;

public sealed class TelemetryProcessor : IHostedService
{
    private readonly IEnumerable<IGpsProvider> _gpsProviders;
    private readonly IMessageBus _bus;
    private readonly ConcurrentDictionary<string, VehicleTelemetry> _store = new();
    private readonly CancellationTokenSource _cts = new();
    private readonly List<Task> _producerTasks = new();
    private Task _consumerTask = null!;

    // Configurable threshold (could be per‑vehicle)
    private const double SpeedThresholdKmh = 120.0;

    public TelemetryProcessor(IEnumerable<IGpsProvider> gpsProviders, IMessageBus bus)
    {
        _gpsProviders = gpsProviders;
        _bus = bus;
    }

    public VehicleTelemetry GetTelemetry(string vehicleId) =>
        _store.TryGetValue(vehicleId, out var t) ? t : null;

    // ----------------------------------------------------
    // IHostedService implementation (started by the host)
    // ----------------------------------------------------
    public Task StartAsync(CancellationToken cancellationToken)
    {
        // 1️⃣ Spin a producer per provider (each vehicle)
        foreach (var provider in _gpsProviders)
        {
            var task = Task.Run(() => ProduceAsync(provider, _cts.Token), cancellationToken);
            _producerTasks.Add(task);
        }

        // 2️⃣ Single consumer that dequeues and processes
        _consumerTask = Task.Run(() => ConsumeAsync(_cts.Token), cancellationToken);
        return Task.CompletedTask;
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        _cts.Cancel();

        await Task.WhenAll(_producerTasks);
        await _consumerTask;
    }

    // ----------------------------------------------------
    // Producer – pushes raw samples into a bounded queue
    // ----------------------------------------------------
    private readonly Channel<GpsSample> _channel = Channel.CreateBounded<GpsSample>(new BoundedChannelOptions(10_000)
    {
        FullMode = BoundedChannelFullMode.DropOldest
    });

    private async Task ProduceAsync(IGpsProvider provider, CancellationToken ct)
    {
        await foreach (var sample in provider.GetStream(ct))
        {
            await _channel.Writer.WriteAsync(sample, ct);
        }
    }

    // ----------------------------------------------------
    // Consumer – computes speed, detects anomalies, updates store
    // ----------------------------------------------------
    private async Task ConsumeAsync(CancellationToken ct)
    {
        var prevSamples = new Dictionary<string, GpsSample>();

        await foreach (var sample in _channel.Reader.ReadAllAsync(ct))
        {
            // 1️⃣ Compute speed (km/h) using haversine distance over time
            double speedKmh = 0;
            if (prevSamples.TryGetValue(sample.VehicleId, out var prev))
            {
                var distanceM = HaversineMeters(prev.Latitude, prev.Longitude,
                                                sample.Latitude, sample.Longitude);
                var secs = (sample.Timestamp - prev.Timestamp).TotalSeconds;
                if (secs > 0) speedKmh = distanceM / secs * 3.6;
            }
            prevSamples[sample.VehicleId] = sample;

            // 2️⃣ Update telemetry store (thread‑safe)
            var telemetry = _store.GetOrAdd(sample.VehicleId,
                id => new VehicleTelemetry { VehicleId = id });
            telemetry.Update(sample, speedKmh);

            // 3️⃣ Raise anomaly if needed
            if (speedKmh > SpeedThresholdKmh)
                _bus.Publish(new SpeedAnomalyEvent(sample.VehicleId, speedKmh, SpeedThresholdKmh));
        }
    }

    // ----------------------------------------------------
    // Haversine helper (static)
    // ----------------------------------------------------
    private static double HaversineMeters(double lat1, double lon1, double lat2, double lon2)
    {
        const double R = 6371e3; // Earth radius in metres
        var φ1 = lat1 * Math.PI / 180;
        var φ2 = lat2 * Math.PI / 180;
        var Δφ = (lat2 - lat1) * Math.PI / 180;
        var Δλ = (lon2 - lon1) * Math.PI / 180;

        var a = Math.Sin(Δφ / 2) * Math.Sin(Δφ / 2) +
                Math.Cos(φ1) * Math.Cos(φ2) *
                Math.Sin(Δλ / 2) * Math.Sin(Δλ / 2);
        var c = 2 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1 - a));
        return R * c;
    }
}
```

**Key points**

* **One producer per vehicle** → scales with the number of assets.  
* **`Channel<T>`** provides a lock‑free, back‑pressure‑aware queue.  
* The consumer runs on a **single background thread** (no race on per‑vehicle state).  
* **Speed anomalies** are broadcast via the **message bus**, keeping the telemetry module oblivious to who consumes them.

